    11  orientation_to_string (SpectreOrientation orientation)
    12  {
    13          switch (orientation) {
    14          case SPECTRE_ORIENTATION_PORTRAIT:
    15                  return "Portrait";
    16          case SPECTRE_ORIENTATION_LANDSCAPE:
    17                  return "Landscape";
    18          case SPECTRE_ORIENTATION_REVERSE_LANDSCAPE:
    19                  return "Reverse Landscape";
    20          case SPECTRE_ORIENTATION_REVERSE_PORTRAIT:
    21                  return "Reverse Portrait";
    22          }
    23
    24          return "Unknown Orientation";
    25  }
