    54  test_rotation (SpectreDocument *document,
    55                 const char      *output)
    56  {
    57          SpectrePage          *page;
    58          SpectreRenderContext *rc;
    59          int                   i;
    60          int                   width_points;
    61          int                   height_points;
    62
    63          page = spectre_document_get_page (document, 0);
    64
    65          spectre_page_get_size (page, &width_points, &height_points);
    66
    67          rc = spectre_render_context_new ();
    68
    69          for (i = 0; i < 4; i++) {
    70                  cairo_surface_t *surface;
    71                  char            *filename;
    72                  int              rotation;
    73                  int              width, height;
    74                  unsigned char   *data = NULL;
    75                  int              row_length;
    76
    77                  rotation = 90 * i;
    78
    79                  if (rotation == 90 || rotation == 270) {
    80                          width = height_points;
    81                          height = width_points;
    82                  } else {
    83                          width = width_points;
    84                          height = height_points;
    85                  }
    86
    87                  spectre_render_context_set_rotation (rc, rotation);
    88                  spectre_page_render (page, rc, &data, &row_length);
    89                  if (spectre_page_status (page)) {
    90                          printf ("Error rendering page %d at rotation %d: %s\n", i, rotation,
    91                                  spectre_status_to_string (spectre_page_status (page)));
    92                          free (data);
    93                          continue;
    94                  }
    95
    96                  surface = cairo_image_surface_create_for_data (data,
    97                                                                 CAIRO_FORMAT_RGB24,
    98                                                                 width, height,
    99                                                                 row_length);
   100
   101                  filename = _spectre_strdup_printf ("%s/page-rotated-%d.png", output, rotation);
   102                  cairo_surface_write_to_png (surface, filename);
   103                  free (filename);
   104
   105                  cairo_surface_destroy (surface);
   106                  free (data);
   107          }
   108
   109          spectre_render_context_free (rc);
   110          spectre_page_free (page);
   111  }
